import sys
from itertools import combinations

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    n = int(next(iterator))
    k = int(next(iterator))

    problems = []
    for _ in range(n):
        row = []
        for _ in range(k):
            row.append(int(next(iterator)))
        problems.append(tuple(row))

    unique_masks = set(problems)
    mask_list = list(unique_masks)

    if len(mask_list) == 1:
        mask = mask_list[0]
        total_ones = sum(mask)
        if total_ones > 0:
            print("NO")
            return
        else:
            print("YES")
            return

    found = False

    for r in range(1, min(len(mask_list), 8) + 1):
        for combo in combinations(mask_list, r):
            valid = True
            for team_idx in range(k):
                count_known = 0
                for mask in combo:
                    if mask[team_idx] == 1:
                        count_known += 1
                if count_known * 2 > r:
                    valid = False
                    break
            if valid:
                found = True
                break
        if found:
            break

    if found:
        print("YES")
    else:
        print("NO")

if __name__ == "__main__":
    main()
